import{E as e,F as t,q as n,w as r}from"./vue.runtime.esm-bundler-DZZTqpJU.js";t();var i={class:`markdown-body`},a={__name:`chmod.zh`,setup(t,{expose:a}){return a({frontmatter:{}}),(t,a)=>(n(),r(`div`,i,[...a[0]||=[e(`<p><code>chmod</code> 命令用于在 Unix/Linux 中更改文件和目录的权限。</p><h2>🧑 用户类别</h2><table><thead><tr><th>符号</th><th>含义</th></tr></thead><tbody><tr><td><code>u</code></td><td>用户（所有者）</td></tr><tr><td><code>g</code></td><td>组</td></tr><tr><td><code>o</code></td><td>其他</td></tr><tr><td><code>a</code></td><td>所有（u+g+o）</td></tr></tbody></table><h2>🔐 权限类型</h2><table><thead><tr><th>符号</th><th>含义</th><th>数字</th></tr></thead><tbody><tr><td><code>r</code></td><td>读</td><td>4</td></tr><tr><td><code>w</code></td><td>写</td><td>2</td></tr><tr><td><code>x</code></td><td>执行</td><td>1</td></tr></tbody></table><h2>📝 符号模式</h2><p>使用 <code>+</code>、<code>-</code> 或 <code>=</code> 来修改权限：</p><pre><code class="language-bash">chmod u+x file      # 为用户添加执行权限
chmod go-w file     # 移除组和其他用户的写权限
chmod a=r file      # 为所有用户设置为只读
</code></pre><h2>🔢 数字（八进制）模式</h2><p>将用户、组和其他用户的权限值组合：</p><table><thead><tr><th>模式</th><th>权限</th><th>含义</th></tr></thead><tbody><tr><td>777</td><td>rwxrwxrwx</td><td>完全访问权限</td></tr><tr><td>755</td><td>rwxr-xr-x</td><td>常用于脚本</td></tr><tr><td>644</td><td>rw-r–r–</td><td>常用于文本文件</td></tr></tbody></table><pre><code class="language-bash">chmod 755 script.sh
chmod 644 notes.txt
</code></pre><h2>🧪 特殊权限标志</h2><p>这些标志超越了基本的读/写/执行权限，用于控制执行上下文和删除行为。</p><h3>🔸 <code>setuid</code>（执行时设置用户 ID）</h3><ul><li><strong>八进制前缀</strong>：<code>4</code></li><li><strong>适用于</strong>：可执行文件</li><li><strong>效果</strong>：执行时，进程以文件所有者的权限运行（而非执行用户的权限）。</li><li><strong>使用场景</strong>：如 <code>passwd</code> 等程序需要提升权限来修改系统文件。</li></ul><pre><code class="language-bash">chmod 4755 /usr/bin/somebinary
# -rwsr-xr-x → 用户字段中的 &#39;s&#39; 替换了 &#39;x&#39;
</code></pre><blockquote><p>⚠️ 滥用会带来安全风险——避免对脚本或用户控制的二进制文件设置此标志。</p></blockquote><h3>🔸 <code>setgid</code>（设置组 ID）</h3><ul><li><strong>八进制前缀</strong>：<code>2</code></li><li><strong>适用于</strong>： <ul><li><strong>文件</strong>：以文件所属组的权限运行。</li><li><strong>目录</strong>：新创建的文件继承该目录的组。</li></ul></li><li><strong>使用场景</strong>：共享项目文件夹，所有文件应属于同一组。</li></ul><pre><code class="language-bash">chmod 2755 /shared/folder
# drwxr-sr-x → 组字段中的 &#39;s&#39;
</code></pre><blockquote><p>📁 在目录上使用此标志可确保协作环境中组的一致性。</p></blockquote><h3>🔸 <code>sticky</code> 位</h3><ul><li><strong>八进制前缀</strong>：<code>1</code></li><li><strong>适用于</strong>：仅目录</li><li><strong>效果</strong>：只有文件所有者（或 root）才能删除或重命名目录内的文件。</li><li><strong>使用场景</strong>：<code>/tmp</code> 目录——防止用户互相删除文件。</li></ul><pre><code class="language-bash">chmod 1777 /tmp
# drwxrwxrwt → 其他用户字段中的 &#39;t&#39;
</code></pre><blockquote><p>🧷 可将其视为共享空间的&quot;删除锁&quot;。</p></blockquote><h2>📂 执行（<code>x</code>）标志：文件与目录的区别</h2><table><thead><tr><th>上下文</th><th><code>x</code> 权限的效果</th></tr></thead><tbody><tr><td><strong>文件</strong></td><td>允许作为程序/脚本执行</td></tr><tr><td><strong>目录</strong></td><td>允许进入目录（<code>cd</code>）并通过名称访问其内容</td></tr></tbody></table><h3>🔍 目录访问矩阵</h3><table><thead><tr><th>权限</th><th>可列出（<code>ls</code>）</th><th>可进入（<code>cd</code>）</th><th>可访问文件</th></tr></thead><tbody><tr><td><code>r</code></td><td>✅</td><td>❌</td><td>✅（已知文件名时）</td></tr><tr><td><code>x</code></td><td>❌</td><td>✅</td><td>✅（已知文件名时）</td></tr><tr><td><code>r+x</code></td><td>✅</td><td>✅</td><td>✅</td></tr></tbody></table><blockquote><p>🧠 没有目录的 <code>x</code> 权限，你无法 <code>cd</code> 进入该目录——即使你可以列出其内容。</p></blockquote><h2>🔍 快速参考</h2><table><thead><tr><th>命令</th><th>描述</th></tr></thead><tbody><tr><td><code>chmod +x file</code></td><td>使文件可执行</td></tr><tr><td><code>chmod -R 755 dir</code></td><td>递归设置权限</td></tr><tr><td><code>chmod u=rwx file</code></td><td>仅将用户权限设置为 rwx</td></tr><tr><td><code>chmod a-x file</code></td><td>移除所有用户的执行权限</td></tr></tbody></table><p>💡 提示：使用 <code>ls -l</code> 查看当前权限。</p>`,34)]]))}};export{a as default};